{
  "kc_id": "KC_CLU_EVAL_001",
  "canonical_name": "Internal Indices Overview",
  "definition": {
    "status": "grounded",
    "grounding_mode": "single_strong_context",
    "text": "Internal indices are unsupervised measures that rely exclusively on information present within the data set.",
    "supporting_evidence_ids": [
      "E2"
    ],
    "supporting_lanes": [
      "context_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "single_strong_context",
    "text": "These indices evaluate the quality of a clustering structure without external information and are categorized into measures of cluster cohesion (compactness, tightness) and cluster separation (isolation).",
    "supporting_evidence_ids": [
      "E2"
    ],
    "supporting_lanes": [
      "context_lane"
    ],
    "abstention_reason": ""
  }
}

{
  "kc_id": "KC_CLU_EVAL_002",
  "canonical_name": "SSE (Cluster Quality)",
  "definition": {
    "status": "grounded",
    "grounding_mode": "single_strong_context",
    "text": "The sum of the squared error (SSE), also known as scatter, is a measure of clustering quality calculated by summing the squared Euclidean distances from each data point to its closest centroid.",
    "supporting_evidence_ids": [
      "E2"
    ],
    "supporting_lanes": [
      "context_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "SSE is used as an objective function to measure clustering quality; a lower SSE indicates that the centroids are a better representation of the points in their cluster and translates to better clustering results.",
    "supporting_evidence_ids": [
      "E2",
      "E3"
    ],
    "supporting_lanes": [
      "context_lane",
      "scope_lane"
    ],
    "abstention_reason": ""
  }
}

